+ '<td class="smx-side ' + cls + '">' + label + '</td>'
+ '<td data-role="' + cls + '-cost">' + price(cost) + '</td><td>' + pct(profit) + '</td>'
+ '<td>' + money(notional) + '</td>'
+ '<td class="smx-gap ' + toneCls + '" data-role="' + cls + '-win">' + gapText + '</td></tr>';
